import{VoxelPart}from'./voxels.js?v=balance-8';
// The rounds carried in the shop and on the aircraft share this mesh with fired missiles.
export function buildMissile(scene,type,parent=null,origin=[0,0,0]){const jet=type==='jet'||type==='swift',p=new VoxelPart(({prop:'Firefly',jet:'Nightjar',swift:'Comet',ufo:'Nova'})[type]+' seeker missile',scene,parent,.035,origin),length=jet?2.05:1.65,r=jet?.13:.115,edge=({prop:'#71efbd',jet:'#c89aff',swift:'#ffc76b',ufo:'#fc80e9'})[type];p.volume([-r,r,-r,r,-length*.5,length*.5],(x,y,z)=>{const radius=r*Math.min(1,(length*.5-z)/.35);return Math.hypot(x,y)<radius?(z>length*.5-.32?'#253044':z< -length*.4?edge:'#dce4e0'):null;});for(let i=0;i<4;i++){const a=i*Math.PI/2;p.rod([Math.cos(a)*r*.6,Math.sin(a)*r*.6,-length*.3],[Math.cos(a)*.31,Math.sin(a)*.31,-length*.43],.045,edge).rod([Math.cos(a)*r,Math.sin(a)*r,length*.15],[Math.cos(a)*.21,Math.sin(a)*.21,length*.08],.035,'#667484');}if(type==='ufo'){for(const z of[-.52,.12])p.volume([-.3,.3,-.3,.3,z-.05,z+.05],(x,y)=>{const d=Math.hypot(x,y);return d<.3&&d>.24?edge:null;});}p.build();p.equipmentSlot='weapons';return p;}
